//
//  HybridTests.swift
//  AgePonyCoreTests
//
//  Known-answer tests for the MLKEM768-X25519 post-quantum recipient
//  (age1pq / mlkem768x25519).
//
//  The vectors were generated by the filippo.io/hpke reference implementation —
//  the exact construction the `age` CLI v1.3.0+ uses — with a fixed identity seed,
//  fixed encapsulation randomness, and a fixed file key. They are the same vectors
//  the Android suite pins in HybridRecipientTests.kt, so passing here proves the
//  two AgePony implementations and standard age all agree byte for byte.
//

import XCTest
@testable import AgePonyCore

final class HybridTests: XCTestCase {

    private func hex(_ s: String) -> Data {
        var d = Data(); var i = s.startIndex
        while i < s.endIndex {
            let j = s.index(i, offsetBy: 2)
            d.append(UInt8(s[i..<j], radix: 16)!); i = j
        }
        return d
    }

    private func hexString(_ d: Data) -> String {
        d.map { String(format: "%02x", $0) }.joined()
    }

