    /// Expected 32-byte sealed body.
    private var expectedBody: Data {
        hex("2998be049fb54ca8f7830eb73b557844730bf0229d48159ac2d95e51eb02d8f3")
    }

    // MARK: - Key derivation

    func testPublicKeyDerivedFromSeedMatchesReference() throws {
        let identity = try HybridIdentity(seed: seed)
        XCTAssertEqual(identity.publicKey.count, 1216)
        XCTAssertEqual(identity.publicKey, expectedPublicKey)
    }

    func testDerivationIsDeterministic() throws {
        let a = try HybridIdentity(seed: seed)
        let b = try HybridIdentity(seed: seed)
        XCTAssertEqual(a.publicKey, b.publicKey)
    }

    // MARK: - Wrap / unwrap against the reference

    func testDeterministicWrapMatchesReferenceVector() throws {
        let recipient = try HybridRecipient(publicKey: expectedPublicKey)
        let stanza = try recipient.wrap(fileKey: fileKey, testRandom: testRandom)

        XCTAssertEqual(stanza.type, "mlkem768x25519")
        XCTAssertEqual(stanza.args.count, 1)
        XCTAssertEqual(try Stanza.base64Decode(stanza.args[0]), expectedEnc)
        XCTAssertEqual(stanza.body, expectedBody)
    }

    func testIdentityUnwrapsReferenceStanza() throws {
        let stanza = Stanza(
            type: "mlkem768x25519",
            args: [Stanza.base64NoPad(expectedEnc)],
            body: expectedBody
        )
        let recovered = try HybridIdentity(seed: seed).unwrap(stanza: stanza)
        XCTAssertEqual(recovered, fileKey)
    }

    func testWrapThenUnwrapRoundTrips() throws {
        let identity = try HybridIdentity.generate()
        let fk = Data((0..<16).map { UInt8($0) })
        let stanza = try identity.recipient().wrap(fileKey: fk)
        XCTAssertEqual(try identity.unwrap(stanza: stanza), fk)
    }

    // MARK: - Rejection

    func testUnwrapReturnsNilForForeignStanza() throws {
        let stanza = Stanza(
            type: "X25519",
            args: [Stanza.base64NoPad(Data(repeating: 0, count: 32))],
            body: Data(repeating: 0, count: 32)
        )
        XCTAssertNil(try HybridIdentity(seed: seed).unwrap(stanza: stanza))
    }

    func testUnwrapReturnsNilForAnotherIdentity() throws {
        let mine = try HybridIdentity.generate()
        let theirs = try HybridIdentity.generate()
        let stanza = try theirs.recipient().wrap(fileKey: fileKey)
        XCTAssertNil(try mine.unwrap(stanza: stanza))
    }

    func testUnwrapReturnsNilForTamperedBody() throws {
        var tampered = Array(expectedBody)
        tampered[0] ^= 1
        let stanza = Stanza(
            type: "mlkem768x25519",
            args: [Stanza.base64NoPad(expectedEnc)],
            body: Data(tampered)
        )
        XCTAssertNil(try HybridIdentity(seed: seed).unwrap(stanza: stanza))
    }

    // MARK: - Bech32 key strings
    //
    // An age1pq recipient runs to 1959 characters, well past BIP-0173's 90-char
    // limit. These would have been undecodable before the cap was raised.

    func testRecipientBech32RoundTrips() throws {
        let identity = try HybridIdentity(seed: seed)
        let encoded = try identity.recipient().ageRecipient

        XCTAssertTrue(encoded.hasPrefix("age1pq1"))
        XCTAssertEqual(encoded.count, 1959)
        XCTAssertEqual(
            hexString(SHA3.sha3_256(Data(encoded.utf8))),
            "ae64ad9ceb44cafc273fc5de5a18f803d6e4d442e047fb4cdcfe00034b29a810"
        )
        XCTAssertEqual(try HybridRecipient(ageRecipient: encoded).publicKey, identity.publicKey)
    }

    func testIdentityBech32RoundTrips() throws {
        let identity = try HybridIdentity(seed: seed)
        let encoded = identity.ageIdentityString
        XCTAssertEqual(encoded, "AGE-SECRET-KEY-PQ-1QQQSYQCYQ5RQWZQFPG9SCRGWPUGPZYSNZS23V9CCRYDPK8QARC0S5DYVQQ")
        XCTAssertEqual(try HybridIdentity(ageIdentity: encoded).seed, identity.seed)
    }

    func testBech32RejectsWrongHRP() throws {
        let x25519Recipient = X25519Identity.generate().ageRecipient
        XCTAssertThrowsError(try HybridRecipient(ageRecipient: x25519Recipient))
    }

    // MARK: - End to end through the age pipeline

    func testEndToEndThroughAgePipeline() throws {
        let identity = try HybridIdentity.generate()
        let plaintext = Data("hello post-quantum age\n".utf8)
        let ciphertext = try Age.encrypt(plaintext: plaintext, to: [try identity.recipient()])
        XCTAssertEqual(try Age.decrypt(ciphertext: ciphertext, identities: [identity]), plaintext)
    }

    func testEndToEndStreamingThroughAgePipeline() throws {
        let identity = try HybridIdentity.generate()
        let plaintext = Data(repeating: 0xAB, count: 200_000)

        let input = InputStream(data: plaintext)
        let output = OutputStream.toMemory()
        try Age.encryptStream(plaintext: input, to: [try identity.recipient()], into: output)
        output.close()
        let ciphertext = output.property(forKey: .dataWrittenToMemoryStreamKey) as? Data ?? Data()

        let back = InputStream(data: ciphertext)
        let plainOut = OutputStream.toMemory()
        try Age.decryptStream(ciphertext: back, identities: [identity], into: plainOut)
        plainOut.close()
        let recovered = plainOut.property(forKey: .dataWrittenToMemoryStreamKey) as? Data ?? Data()

        XCTAssertEqual(recovered, plaintext)
    }

    // MARK: - The post-quantum mixing rule
    //
    // A file readable by an X25519 key is only as quantum-safe as X25519, so age
    // refuses to mix a post-quantum recipient with a classical one rather than
    // silently downgrading the guarantee.

    func testPostQuantumRecipientCarriesLabel() throws {
        let recipient = try HybridIdentity.generate().recipient()
        XCTAssertEqual(recipient.labels, ["postquantum"])
    }

    func testMixingPostQuantumWithClassicalIsRejected() throws {
        let pq = try HybridIdentity.generate().recipient()
        let classical = X25519Identity.generate()
        let classicalRecipient = try X25519Recipient(publicKey: classical.publicKey)

        XCTAssertThrowsError(
            try Age.encrypt(plaintext: Data("nope".utf8), to: [pq, classicalRecipient])
        ) { error in
            XCTAssertEqual(error as? AgeError, .mismatchedRecipientLabels)
        }
    }

    func testTwoPostQuantumRecipientsAreAllowed() throws {
        let a = try HybridIdentity.generate()
        let b = try HybridIdentity.generate()
        let plaintext = Data("two post-quantum readers".utf8)

        let ciphertext = try Age.encrypt(
            plaintext: plaintext,
            to: [try a.recipient(), try b.recipient()]
        )
        XCTAssertEqual(try Age.decrypt(ciphertext: ciphertext, identities: [a]), plaintext)
        XCTAssertEqual(try Age.decrypt(ciphertext: ciphertext, identities: [b]), plaintext)
    }

    func testTwoClassicalRecipientsStillAllowed() throws {
        let a = X25519Identity.generate()
        let b = X25519Identity.generate()
        let plaintext = Data("unlabeled recipients still mix".utf8)

        let ciphertext = try Age.encrypt(
            plaintext: plaintext,
            to: [try X25519Recipient(publicKey: a.publicKey),
                 try X25519Recipient(publicKey: b.publicKey)]
        )
        XCTAssertEqual(try Age.decrypt(ciphertext: ciphertext, identities: [a]), plaintext)
    }
}
